'use strict';

// MODULES //

var tape = require( 'tape' );
var PINF = require( '@stdlib/constants-float64-pinf' );
var NINF = require( '@stdlib/constants-float64-ninf' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var isNegativeZero = require( '@stdlib/math-base-assert-is-negative-zero' );
var isPositiveZero = require( '@stdlib/math-base-assert-is-positive-zero' );
var floor = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof floor, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns the largest integer less than or equal to a given number', function test( t ) {
	t.strictEqual( floor( -4.2 ), -5.0, 'equals -5' );
	t.strictEqual( floor( 9.99999 ), 9.0, 'equals 9' );
	t.strictEqual( floor( 0.0 ), 0.0, 'equals 0' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var v = floor( -0.0 );
	t.strictEqual( isNegativeZero( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var v = floor( +0.0 );
	t.strictEqual( isPositiveZero( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', function test( t ) {
	var v = floor( NaN );
	t.strictEqual( isnan( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var val = floor( PINF );
	t.strictEqual( val, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', function test( t ) {
	var val = floor( NINF );
	t.strictEqual( val, NINF, 'returns expected value' );
	t.end();
});","lineStart":1,"lineEnd":75,"totalLines":75,"truncated":false}},"title":"repos/pc-lib-3456/math-base-special-floor/test/test.js","time":{"start":1783258309997,"end":1783258310000}},"id":"prt_f327a63df001Mo8XFjLmBGDFIW","sessionID":"ses_0cd862a0affeQUFfMdVVKOgL7y","messageID":"msg_f327a54d6001qzJeREdB52K4Vl"}}

